import{_ as e,o,c as a,a2 as r}from"./chunks/framework.G0y0PQA7.js";const l="/relio/shots/ko/update-prefs.png",q=JSON.parse('{"title":"업데이트","description":"","frontmatter":{},"headers":[],"relativePath":"features/update.md","filePath":"features/update.md"}'),i={name:"features/update.md"};function s(n,t,d,u,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="업데이트" tabindex="-1">업데이트 <a class="header-anchor" href="#업데이트" aria-label="Permalink to &quot;업데이트&quot;">​</a></h1><p>새 버전 자동 확인, 업데이트 확인, Relio 안에서 새 버전을 받아 설치하기, 설치 없이 쓰는 실행판의 업데이트를 설명합니다. 1.0.0부터 쓸 수 있습니다.</p><p>처음 실행할 때 알림을 켜는 방법은 빠른 시작의 <a href="/relio/quick/start">처음 시작하기</a>에 있습니다.</p><h2 id="자동-확인-켜기·끄기" tabindex="-1">자동 확인 켜기·끄기 <a class="header-anchor" href="#자동-확인-켜기·끄기" aria-label="Permalink to &quot;자동 확인 켜기·끄기&quot;">​</a></h2><ul><li>처음 실행하면 창 아래에 &quot;새 버전이 나오면 알려 드릴까요? Relio는 하루 한 번 공개 Releases에서 버전 정보만 받습니다.&quot; 띠가 뜹니다. <strong>알려 주세요</strong>는 켜고, <strong>괜찮아요</strong>는 끕니다. 답하지 않고 닫으면 정하지 않은 채(꺼진 것과 같게) 둡니다.</li><li>나중에 바꾸려면 도구 › 환경 설정 › 일반의 **새 버전 자동 확인 (하루 한 번)**을 켜거나 끕니다. 켜면 그 자리에서 한 번 확인합니다.</li><li>켜 두면 앱을 시작하고 조금 뒤 배경에서, 마지막 확인에서 하루가 지났을 때만 확인합니다. 실패해도 다시 시도하지 않고 다음 날 확인합니다.</li><li>설정 아래에 마지막 확인 결과(&quot;마지막 확인: … — 최신 버전입니다&quot; / &quot;… — 새 버전 …&quot; / &quot;… — 확인하지 못했습니다&quot;)가 보입니다.</li></ul><figure class="shot" data-scene="update-prefs"><img src="'+l+'" alt="환경 설정 › 일반의 업데이트 칸 — 새 버전 자동 확인 체크와 설명" loading="lazy"><figcaption>환경 설정 › 일반의 업데이트 칸 — 새 버전 자동 확인 체크와 설명</figcaption></figure><h2 id="무엇을-주고받나" tabindex="-1">무엇을 주고받나 <a class="header-anchor" href="#무엇을-주고받나" aria-label="Permalink to &quot;무엇을 주고받나&quot;">​</a></h2><p>확인은 공개 Releases의 정해진 주소에서 버전 정보 파일을 받기만 합니다. Relio 버전·PC 정보 같은 것을 보내지 않습니다. 다만 GitHub는 접속한 IP 주소를 볼 수 있습니다. 확인 결과는 이 PC의 앱 설정에만 남습니다.</p><h2 id="직접-확인하기" tabindex="-1">직접 확인하기 <a class="header-anchor" href="#직접-확인하기" aria-label="Permalink to &quot;직접 확인하기&quot;">​</a></h2><p>도움말 › **업데이트 확인…**을 누르면 자동 확인 설정과 관계없이 바로 확인합니다. Relio 정보 창과 새 소식 창의 <strong>업데이트 확인</strong> 단추도 같습니다. 결과는 작은 창에 나옵니다.</p><ul><li>최신이면 &quot;지금 쓰는 버전이 최신입니다 (…)&quot;.</li><li>새 버전이 있으면 아래 안내 창.</li><li>실패하면 이유와 <strong>Releases 페이지 열기</strong> 링크(아래 &quot;확인이 안 될 때&quot;).</li></ul><h2 id="새-버전-안내" tabindex="-1">새 버전 안내 <a class="header-anchor" href="#새-버전-안내" aria-label="Permalink to &quot;새 버전 안내&quot;">​</a></h2><p>자동 확인에서 새 버전을 찾으면 창 오른쪽 아래에 &quot;Relio … 버전을 설치할 수 있습니다&quot; 알림이 뜹니다. <strong>자세히</strong>를 누르면 안내 창이 열립니다.</p><ul><li>제목 &quot;새 버전이 있습니다&quot;, <code>지금 … → 새 …</code>, 배포 날짜, 변경 요약, <strong>전체 변경 기록 보기</strong> 링크.</li><li><strong>지금 설치</strong> — 받아서 설치합니다(아래).</li><li><strong>나중에</strong> — 닫습니다. 다음 자동 확인 때 다시 알립니다.</li><li><strong>이 버전 건너뛰기</strong> — 이 버전은 다시 알리지 않습니다. 더 새 버전이 나오면 다시 알립니다. 직접 확인할 때는 건너뛴 버전이어도 &quot;건너뛰기로 한 버전입니다&quot;와 함께 보여 줍니다.</li></ul><h2 id="설치-흐름" tabindex="-1">설치 흐름 <a class="header-anchor" href="#설치-흐름" aria-label="Permalink to &quot;설치 흐름&quot;">​</a></h2><ol><li><strong>지금 설치</strong>를 누르면 같은 창에 진행 막대(&quot;내려받는 중… 받은 크기 / 전체&quot;)가 보입니다. <strong>취소</strong>할 수 있고, 그동안 다른 화면을 써도 됩니다.</li><li>받은 파일의 서명을 확인합니다. 맞지 않으면 설치하지 않습니다.</li><li>저장하지 않은 문서가 있으면 &quot;저장하지 않은 문서 n개가 있습니다. 설치하려면 Relio를 닫아야 합니다.&quot;와 함께 <strong>모두 저장하고 설치</strong> · <strong>저장하지 않고 설치</strong> · <strong>취소</strong>를 묻습니다.</li><li>&quot;설치를 시작합니다. 설치가 끝나면 Relio가 다시 열립니다.&quot; 뒤 Relio가 닫히고 설치가 진행된 다음 다시 열립니다.</li></ol><p>진행 중인 작업(내보내기 등)이 있으면 끝난 뒤 설치할 수 있습니다. 설정·연결 목록·백업은 그대로 남습니다.</p><h2 id="설치-없이-쓰는-실행판" tabindex="-1">설치 없이 쓰는 실행판 <a class="header-anchor" href="#설치-없이-쓰는-실행판" aria-label="Permalink to &quot;설치 없이 쓰는 실행판&quot;">​</a></h2><p><code>Relio_&lt;버전&gt;_x64_portable.zip</code>을 풀어 쓰는 실행판도 확인과 안내는 같습니다. 다만 자동으로 설치하지 않고, 안내 창에 &quot;실행판은 자동으로 설치하지 않습니다. 새 zip을 받아 바꿔 쓰세요.&quot;와 <strong>내려받기 페이지 열기</strong>가 나옵니다. 새 zip을 받아 풀고 그 <code>relio.exe</code>를 씁니다. 설정 폴더는 설치판과 같아서 설정이 그대로 이어집니다.</p><h2 id="확인이-안-될-때" tabindex="-1">확인이 안 될 때 <a class="header-anchor" href="#확인이-안-될-때" aria-label="Permalink to &quot;확인이 안 될 때&quot;">​</a></h2><table tabindex="0"><thead><tr><th>문구</th><th>할 일</th></tr></thead><tbody><tr><td>업데이트 서버에 연결하지 못했습니다. 인터넷 연결이나 회사 네트워크 설정을 확인하세요.</td><td>인터넷·프록시를 확인하거나 Releases 페이지에서 직접 받습니다.</td></tr><tr><td>업데이트 정보를 읽지 못했습니다. 잠시 뒤 다시 확인하거나 Releases 페이지에서 직접 받으세요.</td><td>잠시 뒤 다시 확인합니다.</td></tr><tr><td>받은 파일의 서명이 맞지 않아 설치하지 않았습니다. …</td><td>파일이 손상됐거나 바뀌었을 수 있습니다. Releases 페이지에서 직접 받습니다.</td></tr><tr><td>새 버전을 받지 못했습니다(…).</td><td><strong>다시 시도</strong>하거나 디스크 공간을 확인합니다.</td></tr><tr><td>설치하지 못했습니다. Relio는 지금 버전 그대로입니다. …</td><td>Releases 페이지에서 설치 파일을 받아 직접 설치합니다.</td></tr></tbody></table><p>자동 확인이 실패하면 화면에 아무것도 띄우지 않고 다음 날 다시 확인합니다.</p><div class="info custom-block"><p class="custom-block-title">참고</p><p>회사망에서 프록시를 쓰면 Windows의 사용자 프록시 설정(또는 <code>HTTPS_PROXY</code> 같은 환경 변수)을 따릅니다. 자동 구성 스크립트(PAC)로만 프록시를 정하는 회사망에서는 확인이 되지 않을 수 있으니, 그때는 Releases 페이지에서 직접 받으세요.</p></div><h2 id="손으로-설치하기" tabindex="-1">손으로 설치하기 <a class="header-anchor" href="#손으로-설치하기" aria-label="Permalink to &quot;손으로 설치하기&quot;">​</a></h2><p>언제든 <a href="https://github.com/relio-hq/relio/releases/latest" target="_blank" rel="noreferrer">Releases</a>에서 새 설치 파일 <code>Relio_&lt;버전&gt;_x64-setup.exe</code>를 받아 실행하면 덮어 설치되고 설정은 남습니다. 베타판에서 1.0.0으로 올 때는 한 번 손으로 설치해야 합니다.</p>',25)])])}const g=e(i,[["render",s]]);export{q as __pageData,g as default};
